import { NextRequest, NextResponse } from "next/server";
import { eq, or } from "drizzle-orm";
import { fobRequests } from "@accessbuddy/db";
import { cancelRequestSchema, RequestStatus } from "@accessbuddy/shared";
import { getAuthUser } from "@/lib/auth";
import { resolveTenant } from "@/lib/tenant";
import { withTenant } from "@/lib/with-tenant";
import { transitionRequest } from "@/lib/services/requests";

const CANCELLABLE_STATUSES = [
  RequestStatus.SUBMITTED,
  RequestStatus.AWAITING_PAYMENT,
  RequestStatus.AWAITING_APPROVAL,
  RequestStatus.AWAITING_PROGRAMMING,
  RequestStatus.PROGRAMMED,
  RequestStatus.AWAITING_PICKUP,
];

/**
 * Member self-service cancel. Checks request ownership by userId or email
 * instead of admin permissions.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string; id: string }> }
) {
  try {
    const auth = await getAuthUser();
    if (!auth) {
      return NextResponse.json({ error: "Authentication required" }, { status: 401 });
    }

    const { slug, id: requestId } = await params;
    const tenant = await resolveTenant(slug);
    if (!tenant) {
      return NextResponse.json({ error: "Organisation not found" }, { status: 404 });
    }

    const raw = await request.json();
    const parsed = cancelRequestSchema.safeParse(raw);
    if (!parsed.success) {
      return NextResponse.json({ error: "Reason is required" }, { status: 400 });
    }

    const updated = await withTenant(tenant.id, async (tx) => {
      const [req] = await tx
        .select()
        .from(fobRequests)
        .where(eq(fobRequests.id, requestId))
        .limit(1);

      if (!req) throw new Error("Request not found");

      // Ownership check: must be the requester or match by email
      const isOwner =
        req.requesterId === auth.user.id ||
        (req.orphanEmail && req.orphanEmail === auth.user.email);

      if (!isOwner) {
        throw new Error("You can only cancel your own requests");
      }

      if (!CANCELLABLE_STATUSES.includes(req.status as any)) {
        throw new Error("This request can no longer be cancelled");
      }

      return transitionRequest(tx, {
        requestId,
        tenantId: tenant.id,
        event: "CANCEL",
        actorId: auth.user.id,
        metadata: { reason: parsed.data.reason },
      });
    });

    return NextResponse.json({ request: updated });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "Internal server error";
    if (message.includes("Cannot") || message.includes("not found") || message.includes("only cancel") || message.includes("no longer")) {
      return NextResponse.json({ error: message }, { status: 400 });
    }
    console.error("Member cancel error:", err);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}
