// SUBMITTED and only leaves that state when the member pays or asks for
// an exemption; close the browser at the Stripe step and it sits there
// with no queue column and no reminder. Anything older than the grace
// window is moved to AWAITING_PAYMENT via the normal transition, which
// creates the intent if needed and emails the pay + cancel links.
const abandonedCutoff = new Date(now.getTime() - ABANDONED_PAYMENT_GRACE_MS);
const abandonedRequests = await db
  .select({ id: fobRequests.id, tenantId: fobRequests.tenantId })
  .from(fobRequests)
  .where(
    and(
      eq(fobRequests.status, RequestStatus.SUBMITTED),
      eq(fobRequests.isOrphaned, false),
      eq(fobRequests.paymentExempt, false),
      isNotNull(fobRequests.paymentAmountCents),
      isNotNull(fobRequests.requesterId),
      isNull(fobRequests.paidAt),
      lt(fobRequests.createdAt, abandonedCutoff)
    )
  );

for (const req of abandonedRequests) {
  try {
    await withTenant(req.tenantId, async (tx) => {
      await transitionRequest(tx, {
        requestId: req.id,
        tenantId: req.tenantId,
        event: "PAYMENT_REQUIRED",
        actorId: null,
        metadata: { action: "abandoned_payment_sweep" },
      });
    });
    results.abandonedPaymentsSwept++;
  } catch (err) {
    console.error("Failed to sweep abandoned-payment request:", req.id, err);
  }
}

// 1d. Payment reminders for unpaid requests older than 3 days
const threeDaysAgo = new Date(now.getTime() - 3 * 24 * 60 * 60 * 1000);
const unpaidRequests = await db
  .select({
    id: fobRequests.id,
    tenantId: fobRequests.tenantId,
    requesterId: fobRequests.requesterId,
    orphanEmail: fobRequests.orphanEmail,
    orphanFirstName: fobRequests.orphanFirstName,
    orphanLastName: fobRequests.orphanLastName,
    isOrphaned: fobRequests.isOrphaned,
    paymentAmountCents: fobRequests.paymentAmountCents,
  })

