import { transitionRequest } from "@/lib/services/requests";
import { buildPaymentLinks, formatAmountCents } from "@/lib/payment-links";

export const dynamic = "force-dynamic";

// How long a priced request may sit in SUBMITTED before the nightly sweep
// treats the payment step as abandoned. One hour means anything left over
// from the previous day is swept at the 2am run; same-day cases are visible
// in the queue's "Submitted (unpaid)" section.
const ABANDONED_PAYMENT_GRACE_MS = 60 * 60 * 1000;

