/**
 * Sign a WebAuthn/OTP session payload with the dedicated
 * SESSION_SIGNING_SECRET (Security F1). Never falls back to a hardcoded
 * literal or CRON_SECRET: getSessionSigningSecret() throws if the secret is
 * unset, so callers fail closed rather than issuing an unsigned or
 * trivially-forgeable cookie. Used by the OTP verify route; the WebAuthn
 * login route (apps/web/src/app/api/auth/webauthn/login/route.ts, not owned
 * by this change) still signs independently with the old
 * `CRON_SECRET ?? "webauthn-session-secret"` pattern and needs to be
 * switched to this helper — see the handoff note in the auth-hardening
 * report.
 */
export function signWebauthnSession(
  payload: Pick<WebauthnSessionPayload, "uid" | "email">
): string {
  const fullPayload: WebauthnSessionPayload = {
    uid: payload.uid,
    email: payload.email,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + SESSION_MAX_AGE_SECONDS,
    webauthn: true,
  };
  const payloadStr = JSON.stringify(fullPayload);
  const secret = getSessionSigningSecret();
  const sig = createHmac("sha256", secret).update(payloadStr).digest("base64url");
  return `webauthn.${Buffer.from(payloadStr).toString("base64url")}.${sig}`;
}

