// Leaving the "money owed" states with an intent still live: cancel, reject,
// or an exemption granted after a pay link went out. First ask Stripe
// whether money has in fact been taken (a late webhook leaves paidAt null).
//   - processing: refuse the transition; the webhook will settle it shortly.
//   - succeeded: record paidAt now so the auto-refund branch below fires on
//     CANCEL / REJECT; for an exemption, refuse (admin must refund first).
//   - otherwise: void the intent so a stale pay link cannot take money for
//     a request that no longer needs it. Best-effort.
const LEAVES_PAYMENT_STATES = ["CANCEL", "REJECT", "PAYMENT_EXEMPT", "APPROVE_EXEMPTION"];
if (LEAVES_PAYMENT_STATES.includes(params.event) && !request.paidAt && request.stripePaymentIntentId) {
  const [tenantForIntent] = await tx
    .select({ stripeAccountId: tenants.stripeAccountId })
    .from(tenants)
    .where(eq(tenants.id, params.tenantId))
    .limit(1);
  const stripeAccountId = tenantForIntent?.stripeAccountId ?? null;

  let liveStatus: Awaited<ReturnType<typeof retrievePaymentIntent>>["status"] | null = null;
  try {
    liveStatus = (await retrievePaymentIntent({ paymentIntentId: request.stripePaymentIntentId, stripeAccountId })).status;
  } catch (err) {
    console.error("Failed to read Stripe intent before leaving payment state:", params.requestId, err);
  }

  if (liveStatus === "processing") {
    throw new Error(
      `Cannot ${params.event.toLowerCase().replace(/_/g, " ")}: a payment is still processing in Stripe for this request. Try again in a few minutes.`
    );
  }
  if (liveStatus === "succeeded") {
    if (params.event === "CANCEL" || params.event === "REJECT") {
      const paidNow = new Date();
      await tx.update(fobRequests).set({ paidAt: paidNow }).where(eq(fobRequests.id, params.requestId));
      request.paidAt = paidNow; // lets the auto-refund branch below run
    } else {
      throw new Error(
        "Cannot grant exemption: Stripe shows this request has already been paid. Refund it first, or approve it as paid."
      );
    }
  } else if (liveStatus !== null) {
    try {
      await cancelPaymentIntent({ paymentIntentId: request.stripePaymentIntentId, stripeAccountId });
    } catch (err) {
      console.error("Failed to cancel Stripe intent on", params.event, params.requestId, err);
    }
  }
}

