const RETURNS_TO_STORED_STATUS = [
  "PAYMENT_RECEIVED",
  "PAYMENT_EXEMPT",
  "APPROVE_EXEMPTION",
  "WITHDRAW_PAYMENT_REQUEST",
];
if (params.event === "WITHDRAW_PAYMENT_REQUEST" && !request.paymentReturnStatus) {
  throw new Error(
    "Cannot withdraw a payment request: this request was never issued. Grant an exemption or cancel it instead."
  );
}
if (params.event === "CANCEL" && request.paymentReturnStatus) {
  throw new Error(
    "Cannot cancel: this request was already issued. Withdraw the payment request instead."
  );
}
if (RETURNS_TO_STORED_STATUS.includes(params.event) && request.paymentReturnStatus) {
  updateValues.status = request.paymentReturnStatus;
  updateValues.paymentReturnStatus = null;
  if (params.event === "WITHDRAW_PAYMENT_REQUEST") {
    // The demand could only have been raised on a free credential, so
    // withdrawing it restores the exemption.
    updateValues.paymentExempt = true;
  }
}

