export function RequestStatusBadge({
  status,
  requestType,
  autoClosed,
  paymentRequested,
}: {
  status: string;
  requestType?: string | null;
  /** True for a return the cron closed without collecting the fob. */
  autoClosed?: boolean;
  /**
   * True while a payment demand raised on an already-issued request is
   * outstanding (fob_requests.payment_return_status set). The request sits in
   * awaiting_payment but the credential is in the member's hand, so the badge
   * says so instead of reading like a brand-new request.
   */
  paymentRequested?: boolean;
}) {
  if (paymentRequested) {
    return <Badge variant="outline">Issued, payment requested</Badge>;
  }
  const config = REQUEST_STATUS_CONFIG[status] ?? { variant: "outline" as const };
  return <Badge variant={config.variant}>{requestStatusLabel(status, requestType, autoClosed)}</Badge>;
}

